import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class StringArrayDeserializer_createContextual_TriageGen2Test {

    private StringArrayDeserializer deserializer;
    private DeserializationContext ctxt;
    private BeanProperty property;
    private JavaType stringType;

    @Before
    public void setUp() {
        deserializer = new StringArrayDeserializer();
        ctxt = mock(DeserializationContext.class);
        property = mock(BeanProperty.class);
        stringType = mock(JavaType.class);

        when(ctxt.constructType(String.class)).thenReturn(stringType);
    }







    /**
     * Test Case 4: findConvertingContentDeserializer returns null, 
     * findContextualValueDeserializer returns null.
     * Result: deser is null.
     * Return: 'this'.
     */
    @Test
    public void testCreateContextual_AllNullReturnsThis() throws JsonMappingException {
        StringArrayDeserializer spyDeserializer = spy(new StringArrayDeserializer());

        doReturn(null).when(spyDeserializer).findConvertingContentDeserializer(any(), any(), any());
        when(ctxt.findContextualValueDeserializer(eq(stringType), eq(property))).thenReturn(null);

        JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);

        assertEquals(spyDeserializer, result);
    }


}
